set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {createRequire} from 'node:module';const root='/var/lib/news-flow/qc-public24-20261123',require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),apply=JSON.parse(fs.readFileSync(root+'/apply-result.json')),rows=db.prepare("SELECT * FROM import_receipts WHERE url LIKE '%tieudungso.vn/%' AND imported_at>=?").all(Date.parse(apply.at)),r={at:new Date().toISOString(),rows:[],overlay:db.prepare("SELECT * FROM parser_overlays WHERE site='tieudungso.vn'").get()||null};try{for(const row of rows){const hit=await es.get({index:row.es_index,type:row.es_type,id:row.es_id});r.rows.push({receipt:row,doc:hit._source,article:db.prepare('SELECT * FROM article_links WHERE url=?').get(row.url)});}fs.writeFileSync(root+'/tieudungso-import-inspection.json',JSON.stringify(r,null,2));console.log(JSON.stringify({...r,rows:r.rows.map(x=>({url:x.receipt.url,imported_at:x.receipt.imported_at,publishedDate:x.doc.publishedDate,insertedDate:x.doc.insertedDate,title:x.doc.title,bodyChars:x.doc.content?.length,article:x.article}))}));}finally{db.close();es.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/tieudungso-import-inspection.json "$upload_dir/.qc-public24-import-inspection.json"
